-- public.beast_fed(p_world uuid, p_id integer, p_item text, p_ql double precision, p_care double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.beast_fed(p_world uuid, p_id integer, p_item text, p_ql double precision, p_care double precision DEFAULT NULL::double precision)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_q double precision := least(ql_top(), greatest(0, coalesce(p_ql, 0))); v_bonus double precision;
begin
  select meal_ql(c, p_ql), fed_learn() * meal_ql(c, p_ql) / ql_top() * case when sd.favourite = p_item then fed_favourite() else 1 end
    into v_q, v_bonus
    from creature c join species_def sd on sd.id = c.species
   where c.world_id = p_world and c.id = p_id and c.mode <> 'wild';
  if not found then return; end if;
  update creature set
      fed_bonus = case when v_bonus > 0 and v_bonus >= case when fed_until > now() then coalesce(fed_bonus, 0) else 0 end
                       then v_bonus else fed_bonus end,
      fed_until = case when v_bonus > 0 and v_bonus >= case when fed_until > now() then coalesce(fed_bonus, 0) else 0 end
                       then now() + make_interval(secs => fed_for()) else fed_until end,
      care = least(1, coalesce(p_care, care) + fed_care() * v_q / ql_top()),
      -- And it has eaten (`upkeep_for`).
      unfed = 0
    where world_id = p_world and id = p_id;
end $function$
